#include "metaRoleObject.h"

/* PNG */
static const wxString s_role_64_png = wxT("");

wxIcon ibValueMetaObjectRole::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectRole::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_role_64_png, wxSize(16, 16));

	return icon;
}
